(function(global){'use strict';var definition={"id":"m3-fluorescence","sceneId":"m3","title":"荧光图像智能判读","version":"2.0.0","updated":"2026-11-01","status":"ready","methods":["cv"],"lessonProtocol":"mudlogging-v1","tabs":{"background":{"label":"专业背景","lede":"先认识紫外激发、目标荧光和干扰，再把整图目估改为逐像素圈定。用相同图像比较固定颜色阈值与 U-Net。","judge":[{"label":"示例资料","value":"合成教学数据","desc":"30个模拟样品盘，每盘4张图，共120张64×64图像。按样品盘分成80张训练、16张检查、24张留出；生成器提供目标与干扰掩膜。"},{"label":"核心方法","value":"小型 U-Net","desc":"U-Net 接替逐区域圈定的重复工作，联合颜色与邻域形态输出逐像素得分，保留目标边界和零散区域。"}],"sections":[{"no":1,"title":"真实背景","html":"<div class=\"context-two\"><p>岩屑在紫外光下可能出现荧光。录井人员观察颜色、强度和分布，并结合白光外观、滴照和其他资料描述油气显示。</p><p>矿物、钻井液和拍摄条件也会影响发光。图像中的亮区不等于含油面积，更不能直接换算为含油饱和度。先明确圈定的目标，才谈分级。</p></div><article class=\"technical-board\"><span class=\"mini\">现场全景 / 机制示意</span><h3>同一束紫外光，目标与干扰都可能发亮。</h3><svg viewBox=\"0 0 960 320\" role=\"img\" aria-label=\"紫外光照射岩屑后产生不同发光区域，成像与目标标注分为两步\"><defs><marker id=\"arrow\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M1 1L8 5L1 9\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/></marker></defs><rect x=\"23\" y=\"24\" width=\"192\" height=\"77\" rx=\"6\" fill=\"#e1dcee\" stroke=\"#b8b9aa\"/><text x=\"39\" y=\"53\" class=\"diagram-title\">固定紫外光源</text><text x=\"39\" y=\"76\">灯源、距离与曝光</text><path d=\"M215 65L304 128\" fill=\"none\" stroke=\"#8c76ac\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/><path d=\"M277 119L514 119L548 233H245Z\" fill=\"#e3ded1\" stroke=\"#9da99d\"/><g fill=\"#aaa59a\" stroke=\"#7e8e86\"><path d=\"M278 174L305 151L328 171L312 200Z\"/><path d=\"M344 147L376 139L392 171L366 190Z\"/><path d=\"M406 169L444 150L461 179L435 205Z\"/><path d=\"M477 178L499 162L520 194L491 214Z\"/></g><g fill=\"#d4bd52\"><ellipse cx=\"297\" cy=\"174\" rx=\"10\" ry=\"7\"/><ellipse cx=\"369\" cy=\"165\" rx=\"12\" ry=\"9\"/></g><g fill=\"#818dc0\"><circle cx=\"435\" cy=\"179\" r=\"7\"/><circle cx=\"494\" cy=\"190\" r=\"5\"/></g><text x=\"254\" y=\"271\">目标荧光</text><text x=\"399\" y=\"271\">其他发光与干扰</text><path d=\"M545 150L632 77\" fill=\"none\" stroke=\"#c8ad52\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/><rect x=\"642\" y=\"24\" width=\"290\" height=\"77\" rx=\"6\" fill=\"#e7e1cd\" stroke=\"#b8b9aa\"/><text x=\"658\" y=\"53\" class=\"diagram-title\">相机记录 RGB</text><text x=\"658\" y=\"76\">位置、颜色、强度与分布</text><rect x=\"642\" y=\"149\" width=\"290\" height=\"94\" rx=\"6\" fill=\"#e1e8df\" stroke=\"#b8b9aa\"/><text x=\"658\" y=\"178\" class=\"diagram-title\">约定标注规则</text><text x=\"658\" y=\"201\">逐像素圈定目标区域</text><text x=\"658\" y=\"218\">背景与干扰作为负例</text><path d=\"M785 102V145\" fill=\"none\" stroke=\"#6d999e\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/><text x=\"23\" y=\"311\">明暗不是唯一依据；矿物、钻井液与样品条件也要区分。</text></svg><p class=\"caption\">结构图解释激发与成像；下方数据是合成图，不是现场紫外照片。</p></article><article id=\"mechanism-lab\"></article><div class=\"professional-course\"><article class=\"professional-concept\"><div class=\"concept-heading\"><span>A</span><h3>描述荧光，至少要同时看四个维度</h3></div><div class=\"professional-grid\"><div><svg class=\"professional-svg\" viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"荧光的颜色、强度、分布与丰度\"><defs><marker id=\"prof-arrow-1026707099\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M1 1L8 5L1 9\" fill=\"none\" stroke=\"#75988b\" stroke-width=\"1.5\"/></marker></defs><rect x=\"16\" y=\"28\" width=\"234\" height=\"193\" rx=\"5\" fill=\"#e3e3d6\" stroke=\"#c4c9b5\"/><text x=\"32\" y=\"56\" class=\"prof-title\">点状</text><path d=\"M45 88l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><circle cx=\"62\" cy=\"102\" r=\"4\" fill=\"#c8bb69\"/><path d=\"M87 88l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M129 88l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><circle cx=\"146\" cy=\"102\" r=\"4\" fill=\"#c8bb69\"/><path d=\"M45 131l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M87 131l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><circle cx=\"104\" cy=\"145\" r=\"4\" fill=\"#c8bb69\"/><path d=\"M129 131l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><rect x=\"265\" y=\"28\" width=\"234\" height=\"193\" rx=\"5\" fill=\"#e3e3d6\" stroke=\"#c4c9b5\"/><text x=\"281\" y=\"56\" class=\"prof-title\">斑块状</text><path d=\"M294 88l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"310\" cy=\"102\" rx=\"13\" ry=\"9\" fill=\"#c8bb69\"/><path d=\"M336 88l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"352\" cy=\"102\" rx=\"13\" ry=\"9\" fill=\"#c8bb69\"/><path d=\"M378 88l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M294 131l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M336 131l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M378 131l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><rect x=\"514\" y=\"28\" width=\"234\" height=\"193\" rx=\"5\" fill=\"#e3e3d6\" stroke=\"#c4c9b5\"/><text x=\"530\" y=\"56\" class=\"prof-title\">较均匀</text><path d=\"M543 88l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"559\" cy=\"102\" rx=\"9\" ry=\"7\" fill=\"#c8bb69\"/><path d=\"M585 88l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"601\" cy=\"102\" rx=\"9\" ry=\"7\" fill=\"#c8bb69\"/><path d=\"M627 88l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"643\" cy=\"102\" rx=\"9\" ry=\"7\" fill=\"#c8bb69\"/><path d=\"M543 131l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"559\" cy=\"145\" rx=\"9\" ry=\"7\" fill=\"#c8bb69\"/><path d=\"M585 131l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"601\" cy=\"145\" rx=\"9\" ry=\"7\" fill=\"#c8bb69\"/><path d=\"M627 131l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"643\" cy=\"145\" rx=\"9\" ry=\"7\" fill=\"#c8bb69\"/><text x=\"26\" y=\"258\" class=\"\">分布：目标出现在哪里？</text><text x=\"402\" y=\"258\" class=\"\">丰度：占约定样品范围多少？</text><rect x=\"27\" y=\"278\" width=\"29\" height=\"18\" fill=\"#7b8580\"/><rect x=\"58\" y=\"278\" width=\"29\" height=\"18\" fill=\"#929a78\"/><rect x=\"89\" y=\"278\" width=\"29\" height=\"18\" fill=\"#a8ae70\"/><rect x=\"120\" y=\"278\" width=\"29\" height=\"18\" fill=\"#c4ba68\"/><rect x=\"151\" y=\"278\" width=\"29\" height=\"18\" fill=\"#cfbd55\"/><rect x=\"182\" y=\"278\" width=\"29\" height=\"18\" fill=\"#e3c666\"/><text x=\"232\" y=\"294\" class=\"\">颜色与强度也要同时记录</text></svg><p class=\"caption\">颜色、强度、分布与丰度是不同的观察项目；配色和区域均为示意。</p></div><dl><div><dt>颜色与强度</dt><dd>记录发光色调及明暗；灯源、曝光和油品性质都会影响外观，亮度不能单独代表含油量。</dd></div><div><dt>分布</dt><dd>区分零散点状、斑块状和较均匀的发光；相同面积也可能有完全不同的空间分布。</dd></div><div><dt>丰度</dt><dd>记录发光部分占所观察样品的比例，同时说明分母。本课的面积比例以样品ROI为分母。</dd></div></dl></div></article><article class=\"professional-concept\"><div class=\"concept-heading\"><span>B</span><h3>自然荧光与切割荧光，是互补的观察</h3></div><div class=\"professional-grid\"><div><svg class=\"professional-svg\" viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"白光、自然荧光和切割荧光提供互补观测\"><defs><marker id=\"prof-arrow-1215554493\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M1 1L8 5L1 9\" fill=\"none\" stroke=\"#75988b\" stroke-width=\"1.5\"/></marker></defs><rect x=\"15\" y=\"31\" width=\"233\" height=\"232\" rx=\"5\" fill=\"#e7e2d3\" stroke=\"#c4c9b5\"/><text x=\"30\" y=\"61\" class=\"prof-title\">白光：描述样品</text><rect x=\"264\" y=\"31\" width=\"233\" height=\"232\" rx=\"5\" fill=\"#dedfeb\" stroke=\"#c4c9b5\"/><text x=\"279\" y=\"61\" class=\"prof-title\">紫外：自然荧光</text><rect x=\"513\" y=\"31\" width=\"233\" height=\"232\" rx=\"5\" fill=\"#e7e2d3\" stroke=\"#c4c9b5\"/><text x=\"528\" y=\"61\" class=\"prof-title\">补充：切割荧光</text><path d=\"M48 100l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M90 100l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M132 100l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M48 143l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M90 143l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M132 143l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M297 100l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"313\" cy=\"114\" rx=\"13\" ry=\"9\" fill=\"#c8bb69\"/><path d=\"M339 100l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"355\" cy=\"114\" rx=\"13\" ry=\"9\" fill=\"#c8bb69\"/><path d=\"M381 100l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M297 143l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M339 143l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M381 143l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M570 116h100l-12 91h-76Z\" fill=\"#e1e8d9\" stroke=\"#8ca397\"/><ellipse cx=\"620\" cy=\"190\" rx=\"36\" ry=\"13\" fill=\"#d1c173\"/><text x=\"41\" y=\"240\" class=\"\">颜色 · 粒度 · 油迹</text><text x=\"280\" y=\"240\" class=\"\">颜色 · 强度 · 分布</text><text x=\"533\" y=\"240\" class=\"\">释放现象 · 荧光 · 残留</text><text x=\"24\" y=\"310\" class=\"\">观察互相补充；并非一次图像分割就能完成全部显示评价。</text></svg><p class=\"caption\">只说明观察之间的关系，不提供现场试剂操作；本课图像不包含切割试验。</p></div><dl><div><dt>白光观察</dt><dd>先描述岩性、颜色和油迹，保留样品本身的外观线索。</dd></div><div><dt>自然荧光</dt><dd>紫外光下直接观察岩屑的颜色、强度和分布。没有明显自然荧光，也不能据此排除烃类。</dd></div><div><dt>切割荧光</dt><dd>专业评价还观察溶剂作用后释放物的颜色、荧光、释放快慢和残留，将其与自然荧光结合判断。</dd></div></dl></div></article><article class=\"professional-concept\"><div class=\"concept-heading\"><span>C</span><h3>发光物不止烃类，目标标签必须先约定</h3></div><div class=\"professional-grid\"><div><svg class=\"professional-svg\" viewBox=\"0 0 760 330\" role=\"img\" aria-label=\"不同来源都可能发光，颜色不能单独证明含油\"><defs><marker id=\"prof-arrow-184459787\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"5\" markerHeight=\"5\" orient=\"auto\"><path d=\"M1 1L8 5L1 9\" fill=\"none\" stroke=\"#75988b\" stroke-width=\"1.5\"/></marker></defs><rect x=\"15\" y=\"35\" width=\"233\" height=\"228\" rx=\"5\" fill=\"#e5e5d6\" stroke=\"#c4c9b5\"/><text x=\"30\" y=\"67\" class=\"prof-title\">烃类显示线索</text><path d=\"M47 105l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M89 105l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M131 105l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M47 148l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M89 148l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M131 148l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"83\" cy=\"142\" rx=\"24\" ry=\"16\" fill=\"#cbbd63\"/><text x=\"33\" y=\"239\" class=\"\">需结合其他显示</text><rect x=\"264\" y=\"35\" width=\"233\" height=\"228\" rx=\"5\" fill=\"#e5e5d6\" stroke=\"#c4c9b5\"/><text x=\"279\" y=\"67\" class=\"prof-title\">矿物自身发光</text><path d=\"M296 105l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M338 105l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M380 105l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M296 148l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M338 148l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M380 148l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"332\" cy=\"142\" rx=\"24\" ry=\"16\" fill=\"#8ca5bf\"/><text x=\"282\" y=\"239\" class=\"\">颜色可能与烃类重叠</text><rect x=\"513\" y=\"35\" width=\"233\" height=\"228\" rx=\"5\" fill=\"#e5e5d6\" stroke=\"#c4c9b5\"/><text x=\"528\" y=\"67\" class=\"prof-title\">人工材料污染</text><path d=\"M545 105l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M587 105l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M629 105l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M545 148l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M587 148l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><path d=\"M629 148l25-8 12 20-13 19-25-7Z\" fill=\"#969f92\" stroke=\"#73887e\"/><ellipse cx=\"581\" cy=\"142\" rx=\"24\" ry=\"16\" fill=\"#a7a66e\"/><text x=\"531\" y=\"239\" class=\"\">需与使用材料对照</text><text x=\"25\" y=\"311\" class=\"\">本课蓝色干扰为人为设定；现场不能把蓝色一律排除。</text></svg><p class=\"caption\">目标、矿物与污染物可能同时发光；蓝色仅是本例人为设置的干扰颜色。</p></div><dl><div><dt>矿物荧光</dt><dd>某些矿物自身会发光，其颜色也可能与烃类重叠。不能把某一种颜色永久当成“含油”。</dd></div><div><dt>人工材料</dt><dd>钻井液添加剂、润滑材料等也可能带来荧光，需结合现场使用材料的对照记录。</dd></div><div><dt>分割标签</dt><dd>先明确本例圈哪些区域、排除哪些干扰，再比较算法。像素标签只是图像任务的约定，不是现场含油等级。</dd></div></dl></div></article></div><p class=\"professional-bridge\">荧光分割先解决“约定的目标在哪里”。理解油气显示的观察项目，才能知道面积统计代表什么。</p><p class=\"source-line\">专业依据：<a href=\"https://wiki.aapg.org/Show_evaluation\" target=\"_blank\" rel=\"noopener noreferrer\">AAPG · 油气显示与荧光评价 ↗</a> · <a href=\"https://www.slb.com/resource-library/oilfield-review/defining-series/defining-mud-logging\" target=\"_blank\" rel=\"noopener noreferrer\">SLB · 岩屑观察与描述 ↗</a></p>"},{"no":2,"title":"技术前沿","html":"<p><a href=\"https://doi.org/10.2139/ssrn.5963110\" target=\"_blank\" rel=\"noopener noreferrer\">A semantic segmentation network of fluorescent detection of drilling cuttings for lithology assessment ↗</a>：空间与上下文双分支联合提取特征，细化发光区域分割。 所引版本为预印本；本课只运行基础U-Net，不复现论文双分支结构。</p><p><a href=\"https://doi.org/10.1016/j.jhazmat.2025.139374\" target=\"_blank\" rel=\"noopener noreferrer\">Real-time oil spill concentration assessment through fluorescence imaging and deep learning ↗</a>：CNN提取特征，再回归浓度。 这是溢油油样研究，成像与岩屑不同；说明标定与任务定义的重要性，不能把本课面积换算为浓度。</p>"},{"no":3,"title":"示例数据","html":"<p>30个模拟样品盘，每盘4张图，共120张64×64图像。按样品盘分成80张训练、16张检查、24张留出；生成器提供目标与干扰掩膜。</p>"},{"no":4,"title":"技术难度与参考方向","html":"<p>网络骨架基础，难点在灯源、曝光、干扰荧光和边界标注；真正应用需要现场样品与独立成像批次。</p>"},{"no":5,"title":"术语对照表","html":"<table><tr><td>紫外激发 / UV</td><td>用紫外光让部分物质发出可见光。</td><td>成像条件，而不是类别标签。</td></tr><tr><td>荧光分布</td><td>亮区的位置与覆盖情况。</td><td>像素区域与空间形态。</td></tr><tr><td>干扰荧光</td><td>目标之外也可能出现发光。</td><td>分割模型需要排除的负例。</td></tr><tr><td>曝光参照</td><td>用相同参照调整明暗。</td><td>两种方法共同的预处理。</td></tr><tr><td>ROI / 样品区域</td><td>只在约定的样品范围内统计。</td><td>二值统计掩膜。</td></tr><tr><td>分割标签</td><td>每个像素是否属于目标。</td><td>监督学习的目标值。</td></tr><tr><td>编码器 / 解码器</td><td>先理解局部特征，再恢复位置。</td><td>U-Net的压缩与上采样。</td></tr><tr><td>跳接 / Skip connection</td><td>把浅层位置细节传给后面的层。</td><td>跨层特征拼接。</td></tr><tr><td>分割阈值</td><td>多大得分才圈为目标。</td><td>对保存得分作后处理。</td></tr><tr><td>IoU / 交并比</td><td>圈中区域与标签重合多少。</td><td>交集÷并集，越大越接近标签。</td></tr><tr><td>自然荧光</td><td>紫外光下直接看到的岩屑发光。</td><td>成像观测，需区分来源。</td></tr><tr><td>切割荧光 / Cut fluorescence</td><td>溶剂作用后释放物的荧光表现。</td><td>与原始图像不同的补充观测。</td></tr><tr><td>荧光丰度</td><td>发光部分在样品中的占比。</td><td>先约定统计分母。</td></tr></table>"}],"page":{"html":"demo/background.html","view":"background","height":1040}},"workflow":{"label":"案例流程","title":"亮点在哪里，比整张图有多亮更重要。","lead":["你收到24张留出合成荧光图。按给定标注规则圈出目标荧光，同时排除蓝色亮点干扰，比较弱荧光是否被漏圈。"],"stats":[["流程","6步"],["核心算法","小型 U-Net"],["数据","合成教学资料"]],"steps":[{"name":"约定圈定目标","role":"资料与任务","do":"本例的任务是目标荧光区域分割，先区分目标、干扰与背景。","effect":"明确的逐像素目标。","trap":"这里的目标颜色、形态和标签都是教学设定。目标面积比例仅是本例图像统计，不是含油饱和度或现场荧光等级。"},{"name":"核对数据与质量","role":"资料与任务","do":"检查原始图、样品ROI、曝光参照和生成器像素标签。同盘四张图整组隔开。","effect":"有成像与标签说明的输入图。","trap":"这里的目标颜色、形态和标签都是教学设定。目标面积比例仅是本例图像统计，不是含油饱和度或现场荧光等级。"},{"name":"传统方法处理","role":"资料与任务","do":"用共同曝光校正后的R、G、B颜色条件圈出目标，改变阈值观察漏圈。","effect":"当前颜色阈值下的二值区域。","trap":"这里的目标颜色、形态和标签都是教学设定。目标面积比例仅是本例图像统计，不是含油饱和度或现场荧光等级。"},{"name":"用 U-Net 圈出区域","role":"重点 · AI处理","do":"编码器读取颜色和局部结构，解码器结合跳接恢复像素位置，得到目标区域得分。","effect":"64×64目标得分图与分割掩膜。","trap":"这里的目标颜色、形态和标签都是教学设定。目标面积比例仅是本例图像统计，不是含油饱和度或现场荧光等级。"},{"name":"比较多圈与漏圈","role":"重点 · AI处理","do":"同一图像下比较固定RGB阈值与U-Net；红色为多圈，蓝色为漏圈，标签来自生成器。","effect":"交并比IoU、面积比例与差异图。","trap":"这里的目标颜色、形态和标签都是教学设定。目标面积比例仅是本例图像统计，不是含油饱和度或现场荧光等级。"},{"name":"形成逐图记录","role":"资料与任务","do":"汇总每张图的目标面积比例，保留原图、预测掩膜和标注规则。","effect":"可导出的图像分割结果表。","trap":"这里的目标颜色、形态和标签都是教学设定。目标面积比例仅是本例图像统计，不是含油饱和度或现场荧光等级。"}],"metrics":{"title":"基础算法与本课实现","html":"<svg class=\"network-diagram\" viewBox=\"0 0 960 148\" role=\"img\" aria-label=\"小型 U-Net从输入到结果的处理路径\"><rect x=\"10\" y=\"35\" width=\"219\" height=\"79\" rx=\"6\" fill=\"#eee5d4\" stroke=\"#b8b9aa\"/><text x=\"26\" y=\"64\" class=\"diagram-title\">校正后的RGB</text><text x=\"26\" y=\"87\">本例实际输入形状</text><path d=\"M231 74H246\" fill=\"none\" stroke=\"#6d999e\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/><rect x=\"249\" y=\"35\" width=\"219\" height=\"79\" rx=\"6\" fill=\"#dce8df\" stroke=\"#b8b9aa\"/><text x=\"265\" y=\"64\" class=\"diagram-title\">两级编码压缩</text><text x=\"265\" y=\"87\">小型 U-Net</text><path d=\"M470 74H485\" fill=\"none\" stroke=\"#6d999e\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/><rect x=\"488\" y=\"35\" width=\"219\" height=\"79\" rx=\"6\" fill=\"#eee5d4\" stroke=\"#b8b9aa\"/><text x=\"504\" y=\"64\" class=\"diagram-title\">跳接与解码</text><text x=\"504\" y=\"87\">由训练资料拟合</text><path d=\"M709 74H724\" fill=\"none\" stroke=\"#6d999e\" stroke-width=\"2.5\" marker-end=\"url(#arrow)\"/><rect x=\"727\" y=\"35\" width=\"219\" height=\"79\" rx=\"6\" fill=\"#eee5d4\" stroke=\"#b8b9aa\"/><text x=\"743\" y=\"64\" class=\"diagram-title\">逐像素目标得分</text><text x=\"743\" y=\"87\">与原记录逐项对照</text></svg><p>通道数8→16→32→16→8，两个池化层与对应跳接。模型学习像素标签；页面阈值只改变保存得分的分割结果。</p>"},"page":{"html":"demo/workflow.html","view":"workflow","height":1040}},"demo":{"label":"可运行示范","mode":"page","html":"demo/identify.html","view":"demo","height":1040,"intro":"调整曝光、ROI和传统颜色阈值，在浏览器运行U-Net，比较逐像素多圈、漏圈和面积。当前是有生成器标签的合成教学实验。"}}};['background','workflow','demo'].forEach(function(name){var tab=definition.tabs[name],frame=null;function resize(event){if(frame&&event.source===frame.contentWindow&&event.data){var h=event.data.__lessonHeight;if(typeof h==='number'&&isFinite(h))frame.style.height=Math.max(700,Math.min(14000,h+2))+'px';}}tab.mount=function(root){tab.unmount();frame=document.createElement('iframe');frame.src="m3-fluorescence-case/"+(tab.page?tab.page.html:tab.html)+'?v='+definition.version;frame.setAttribute('title',"M3 · "+tab.label);frame.setAttribute('sandbox','allow-scripts allow-popups allow-popups-to-escape-sandbox allow-downloads');frame.setAttribute('referrerpolicy','no-referrer');frame.style.cssText='display:block;width:100%;height:1040px;border:0;border-radius:10px;background:#fcf7eb';global.addEventListener('message',resize);root.appendChild(frame);};tab.unmount=function(){global.removeEventListener('message',resize);if(frame)frame.remove();frame=null;};});global.Cases.register(definition);}(window));
